// === PARSE SMS ACTION DETECTION ===
const transcriptData = $('Prepare Transcript').first().json;
const callerPhone = transcriptData.callerPhone || '';
const calledNumber = $('Load Session').first()?.json?.called_number || '';

let action = {};
const raw = $json?.choices?.[0]?.message?.content
  || $json?.message?.content || '{}';

try {
  const cleaned = raw.replace(/```json|```/g, '').trim();
  action = JSON.parse(cleaned);
} catch (e) {
  return [{ json: { 
    needs_sms: false, 
    needs_calendar: false,
    has_specific_time: false,
    error: 'parse error',
    raw: raw 
  }}];
}

// Can't send SMS to web client users (client:user_xxx)
if (callerPhone.startsWith('client:')) {
  return [{ json: {
    needs_sms: false,
    needs_calendar: action.needs_calendar === true,
    has_specific_time: action.has_specific_time === true,
    meeting_datetime: action.meeting_datetime || '',
    meeting_duration_minutes: action.meeting_duration_minutes || 30,
    sms_type: 'none',
    sms_body: '',
    calendar_subject: action.calendar_subject || '',
    calendar_notes: action.calendar_notes || '',
    caller_name: action.caller_name || '',
    caller_email: action.caller_email || '',
    callerPhone: callerPhone,
    calledNumber: calledNumber,
    callSid: transcriptData.callSid || '',
    tier: transcriptData.tier || 'starter',
    skipped_reason: 'web client - no real phone number for SMS'
  }}];
}

return [{
  json: {
    needs_sms: action.needs_sms === true,
    needs_calendar: action.needs_calendar === true,
    has_specific_time: action.has_specific_time === true,
    meeting_datetime: action.meeting_datetime || '',
    meeting_duration_minutes: action.meeting_duration_minutes || 30,
    sms_type: action.sms_type || 'none',
    sms_body: action.sms_body || '',
    calendar_subject: action.calendar_subject || '',
    calendar_notes: action.calendar_notes || '',
    caller_name: action.caller_name || '',
    caller_email: action.caller_email || '',
    callerPhone: callerPhone,
    calledNumber: calledNumber,
    callSid: transcriptData.callSid || '',
    tier: transcriptData.tier || 'starter'
  }
}];

// === AUTO-CREATE MEETING ===
// All data in $json from Wait For Calendar Data merge (combineAll):
// - From HubSpot chain: hubspot_contact_id
// - From Parse SMS Action: meeting_datetime, calendar_subject, etc.
const data = $json;

const meetingDatetime = data.meeting_datetime || '';
const durationMin = data.meeting_duration_minutes || 30;
const callerName = data.caller_name || 'Caller';
const callerPhone = data.callerPhone || '';
const callSid = data.callSid || '';
const subject = data.calendar_subject || 'Consultation with ' + callerName;
const notes = data.calendar_notes || '';

// Convert ISO datetime to milliseconds
let startMs = new Date(meetingDatetime).getTime();

// If parsing failed or date is way in the past, fall back to 24h from now
const now = Date.now();
if (isNaN(startMs) || startMs < now - (365 * 24 * 60 * 60 * 1000)) {
  startMs = now + (24 * 60 * 60 * 1000);
}

// If timestamp is in seconds instead of milliseconds
if (startMs < 1000000000000) {
  startMs = startMs * 1000;
}

const endMs = startMs + (durationMin * 60 * 1000);
const contactId = data.hubspot_contact_id || '';

const body = '📅 Auto-scheduled Meeting' +
  '\n\nSubject: ' + subject +
  '\nRequested: ' + meetingDatetime +
  '\nResolved to: ' + new Date(startMs).toISOString() +
  '\nNotes: ' + notes +
  '\nCaller: ' + callerName + ' (' + callerPhone + ')' +
  '\nCall SID: ' + callSid;

return [{
  json: {
    startTime: startMs,
    endTime: endMs,
    title: subject,
    body: body,
    contactId: contactId
  }
}];

// === MERGE CUSTOMER ID ===
const transcriptData = $('Prepare Transcript').first().json;

const inputData = $input.first()?.json;
const customerId = inputData?.customer_id || null;

return [{
  json: {
    ...transcriptData,
    customer_id: customerId
  }
}];

// Get existing HubSpot contact ID
// HubSpot v2 search returns results with 'vid' not 'id'
const results = $json.results || [];
const contactId = results[0]?.id || results[0]?.vid || null;

return [{
  json: {
    hubspot_contact_id: contactId,
    is_new_contact: false,
    transcript: $('Prepare Transcript').first().json.transcript,
    callerPhone: $('Prepare Transcript').first().json.callerPhone,
    callSid: $('Prepare Transcript').first().json.callSid,
    tier: $('Prepare Transcript').first().json.tier
  }
}];

// Get new HubSpot contact ID
// HubSpot v2 node returns 'vid', not 'id'
const contactId = $json.id || $json.vid || null;

return [{
  json: {
    hubspot_contact_id: contactId,
    is_new_contact: true,
    transcript: $('Prepare Transcript').first().json.transcript,
    callerPhone: $('Prepare Transcript').first().json.callerPhone,
    callSid: $('Prepare Transcript').first().json.callSid,
    tier: $('Prepare Transcript').first().json.tier
  }
}];

// === FORMAT VOICEMAIL EMAIL ===
const data = $('Prepare Transcript').first().json;

const callerPhone = data.callerPhone || 'Unknown';
const startTime = data.startTime ? new Date(data.startTime).toLocaleString('en-US', {
  timeZone: 'America/Chicago',
  weekday: 'short',
  year: 'numeric',
  month: 'short',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
}) : 'Unknown';
const endTime = data.endTime ? new Date(data.endTime).toLocaleString('en-US', {
  timeZone: 'America/Chicago',
  hour: '2-digit',
  minute: '2-digit'
}) : 'Unknown';
const tier = (data.tier || 'starter').charAt(0).toUpperCase() + (data.tier || 'starter').slice(1);
const transcript = data.transcript || 'No speech detected.';
const totalTurns = data.totalTurns || 0;

const subject = '📞 Voicemail: ' + callerPhone + ' | ' + startTime;

const htmlBody = '<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;"><div style="background:#1B2A4A;color:white;padding:16px 24px;border-radius:8px 8px 0 0;"><h2 style="margin:0;font-size:20px;">📞 Voicemail Notification</h2><p style="margin:4px 0 0;opacity:0.85;font-size:13px;">360 Group AI Voice Agent</p></div><div style="border:1px solid #e0e0e0;border-top:none;padding:24px;border-radius:0 0 8px 8px;"><table style="width:100%;border-collapse:collapse;margin-bottom:20px;"><tr><td style="padding:10px 12px;font-weight:bold;color:#1B2A4A;border-bottom:1px solid #f0f0f0;width:140px;">Caller</td><td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;font-size:16px;">' + callerPhone + '</td></tr><tr><td style="padding:10px 12px;font-weight:bold;color:#1B2A4A;border-bottom:1px solid #f0f0f0;">Call Time</td><td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;">' + startTime + ' — ' + endTime + '</td></tr><tr><td style="padding:10px 12px;font-weight:bold;color:#1B2A4A;border-bottom:1px solid #f0f0f0;">Tier</td><td style="padding:10px 12px;border-bottom:1px solid #f0f0f0;">' + tier + '</td></tr><tr><td style="padding:10px 12px;font-weight:bold;color:#1B2A4A;">Interaction</td><td style="padding:10px 12px;">' + totalTurns + ' turns</td></tr></table><h3 style="color:#1B2A4A;margin:0 0 8px;font-size:15px;">Transcript</h3><div style="background:#f8f9fa;border:1px solid #e8e8e8;border-radius:6px;padding:16px;white-space:pre-wrap;font-size:13px;line-height:1.6;color:#333;">' + transcript + '</div><div style="margin-top:24px;padding-top:16px;border-top:1px solid #f0f0f0;"><p style="color:#888;font-size:11px;margin:0;">This voicemail notification was generated automatically by the 360 Group AI Voice Agent. Call SID: ' + (data.callSid || 'N/A') + '</p></div></div></div>';

return [{
  json: {
    subject: subject,
    htmlBody: htmlBody,
    callerPhone: callerPhone,
    callSid: data.callSid
  }
}];

// Caller has opted out of SMS - skip sending
return [{ json: { 
  skipped: true, 
  reason: 'caller opted out of SMS',
  callerPhone: $('Parse SMS Action').first().json.callerPhone,
  callSid: $('Parse SMS Action').first().json.callSid
}}];

