// === BUILD FOLLOW-UP EMAIL ===
const smsData = $('Parse SMS Action').first().json;
const transcript = $('Prepare Transcript').first().json;
const callerName = smsData.caller_name || 'Valued Caller';
const callerEmail = smsData.caller_email || '';
const callerPhone = smsData.callerPhone || '';
const smsType = smsData.sms_type || 'summary';
const calendarSubject = smsData.calendar_subject || '';
const calendarNotes = smsData.calendar_notes || '';
const meetingDatetime = smsData.meeting_datetime || '';
const callSid = transcript.callSid || '';
const tier = transcript.tier || 'starter';
const callTranscript = transcript.transcript || '';

// Format meeting time if available
let meetingInfo = '';
if (meetingDatetime) {
  const d = new Date(meetingDatetime);
  meetingInfo = d.toLocaleString('en-US', {
    timeZone: 'America/Chicago',
    weekday: 'long',
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit'
  });
}

const bookingLink = 'https://meetings-na2.hubspot.com/dmmc?uuid=5cab945b-e445-4a57-8b57-eb6ce7bc1933';

// Build summary from transcript (first 800 chars)
const summaryText = callTranscript.length > 800 
  ? callTranscript.substring(0, 800) + '...' 
  : callTranscript;

const subject = meetingInfo 
  ? 'Your Meeting with 360 Group - ' + calendarSubject
  : 'Thank You for Calling 360 Group - Call Summary';

const htmlBody = '<div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;">' +
  '<div style="background:#1B2A4A;color:white;padding:20px 24px;border-radius:8px 8px 0 0;">' +
    '<h2 style="margin:0;font-size:22px;">360 Group</h2>' +
    '<p style="margin:4px 0 0;opacity:0.85;font-size:13px;">Your AI-Powered Business Partner</p>' +
  '</div>' +
  '<div style="border:1px solid #e0e0e0;border-top:none;padding:24px;border-radius:0 0 8px 8px;">' +
    '<p style="font-size:16px;color:#333;">Hi ' + callerName + ',</p>' +
    '<p style="color:#555;">Thank you for calling 360 Group! Here\'s a summary of our conversation:</p>' +

    // Meeting section (if applicable)
    (meetingInfo ? 
      '<div style="background:#f0f7ff;border-left:4px solid #1B2A4A;padding:16px;margin:16px 0;border-radius:0 6px 6px 0;">' +
        '<h3 style="margin:0 0 8px;color:#1B2A4A;">📅 Meeting Scheduled</h3>' +
        '<p style="margin:4px 0;"><strong>Date & Time:</strong> ' + meetingInfo + '</p>' +
        '<p style="margin:4px 0;"><strong>Subject:</strong> ' + calendarSubject + '</p>' +
        (calendarNotes ? '<p style="margin:4px 0;"><strong>Notes:</strong> ' + calendarNotes + '</p>' : '') +
      '</div>' : '') +

    // Booking link (if no specific time set but calendar requested)
    (smsData.needs_calendar && !meetingInfo ?
      '<div style="background:#f0f7ff;border-left:4px solid #1B2A4A;padding:16px;margin:16px 0;border-radius:0 6px 6px 0;">' +
        '<h3 style="margin:0 0 8px;color:#1B2A4A;">📅 Schedule Your Meeting</h3>' +
        '<p style="margin:4px 0;">Pick a time that works for you:</p>' +
        '<a href="' + bookingLink + '" style="display:inline-block;background:#1B2A4A;color:white;padding:10px 24px;border-radius:6px;text-decoration:none;margin:8px 0;">Book a Meeting</a>' +
      '</div>' : '') +

    // Call summary
    '<div style="margin:20px 0;">' +
      '<h3 style="color:#1B2A4A;margin:0 0 8px;">📝 Call Summary</h3>' +
      '<div style="background:#f8f9fa;border:1px solid #e8e8e8;border-radius:6px;padding:16px;white-space:pre-wrap;font-size:13px;line-height:1.6;color:#333;">' +
        summaryText +
      '</div>' +
    '</div>' +

    '<p style="color:#555;margin-top:20px;">Need anything else? Simply reply to this email or call us anytime.</p>' +
    '<p style="color:#555;">Best regards,<br><strong>360 Group Team</strong></p>' +

    '<div style="margin-top:24px;padding-top:16px;border-top:1px solid #f0f0f0;">' +
      '<p style="color:#999;font-size:11px;margin:0;">This email was sent by the 360 Group AI Voice Agent following your call.</p>' +
    '</div>' +
  '</div>' +
'</div>';

return [{
  json: {
    to: callerEmail,
    subject: subject,
    htmlBody: htmlBody,
    callerName: callerName,
    callerPhone: callerPhone,
    callSid: callSid
  }
}];
